//go:build arm64

package fletcher4

// sumNEON is generated by go-asmgen (internal/gen) into kernel_arm64.s. nblocks
// counts 32-byte blocks of p; the four lanes (two 2-lane sets) are stored to
// out[g*4+j].
//
//go:noescape
func sumNEON(p *byte, nblocks int, out *[32]uint64)

func allKernels() []kernel {
	return []kernel{{"neon", 4, 32, sumNEON, true}}
}
